/**
 * Writes `supabase/functions/todoist-daily/single-file.ts`: the Edge Function
 * with the shared Todoist module (`supabase/functions/_shared/todoist.ts`)
 * inlined, for pasting into the Supabase dashboard's function editor (which
 * has no `_shared` folder). The CLI/GitHub deployment keeps using `index.ts`.
 *
 * Run `node scripts/build-function-single-file.mjs` after changing either
 * source file; a unit test fails while the generated file is outdated.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const fn = join(root, 'supabase', 'functions');

/**
 * Builds the single-file source.
 *
 * @param {string} shared Source of `_shared/todoist.ts`.
 * @param {string} index Source of `todoist-daily/index.ts`.
 * @returns {string} The combined module.
 */
export function buildSingleFile(shared, index) {
  // Drop the imports of the shared module; everything it exports is inlined.
  const withoutShared = index.replace(
    /^import(?: type)? \{[^}]*\} from '\.\.\/_shared\/todoist\.ts';\n/gm,
    '',
  );
  // Remaining imports (e.g. supabase-js) go to the top of the file.
  const imports = withoutShared.match(/^import .*;$/gm) ?? [];
  const body = withoutShared.replace(/^import .*;\n/gm, '');
  return [
    '// GENERATED by scripts/build-function-single-file.mjs - do not edit.',
    '// Edge Function `todoist-daily` as one file for the Supabase dashboard editor.',
    '// Sources: supabase/functions/_shared/todoist.ts + supabase/functions/todoist-daily/index.ts',
    ...imports,
    '',
    '// ---- _shared/todoist.ts ----',
    shared.trimEnd(),
    '',
    '// ---- todoist-daily/index.ts ----',
    body.trimEnd(),
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const out = buildSingleFile(
    readFileSync(join(fn, '_shared', 'todoist.ts'), 'utf8'),
    readFileSync(join(fn, 'todoist-daily', 'index.ts'), 'utf8'),
  );
  writeFileSync(join(fn, 'todoist-daily', 'single-file.ts'), out);
  console.log('wrote supabase/functions/todoist-daily/single-file.ts');
}
